code='''def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    # Find maximal rectangular zones by local 2x2 supports, then fill in cells
    # whose surrounding pattern belongs to a same-color solid rectangle.
    for color in set(sum(grid,[]))-{0}:
        # Enumerate rectangles of at least 2x2 with >=80% target-color cells.
        rects=[]
        for r1 in range(h):
          for r2 in range(r1+1,h):
            for c1 in range(w):
              for c2 in range(c1+1,w):
                area=(r2-r1+1)*(c2-c1+1)
                if area>80: continue
                n=sum(grid[r][c]==color for r in range(r1,r2+1) for c in range(c1,c2+1))
                if n/area>=.85 and n>=6: rects.append((n,area,r1,r2,c1,c2))
        # Use rectangles matching objects; larger candidates naturally encompass markings.
        for n,a,r1,r2,c1,c2 in rects:
          for r in range(r1,r2+1):
            for c in range(c1,c2+1):
              if grid[r][c]==color: out[r][c]=color
    return out
'''
